const tasks = [
  {
    id: 'incident',
    taskState: 'Preserve Aurora-17 and decide incident INC-2048.',
    system: 'Hard constraint: preserve project Aurora-17.',
    current: 'Current verified facts: incident INC-2048 affects Aurora-17 and the required decision is ROLLBACK.',
  },
  {
    id: 'release',
    taskState: 'Preserve Atlas-5 and decide the release gate.',
    system: 'Hard constraint: preserve release Atlas-5.',
    current: 'Current verified facts: Atlas-5 is BLOCKED because the security gate failed.',
  },
  {
    id: 'migration',
    taskState: 'Preserve Northstar migration facts.',
    system: 'Hard constraint: preserve customer Northstar.',
    current: 'Current verified facts: Northstar targets eu-central and the approved window starts at 02:00 UTC.',
  },
];

const cases = [];
for (const task of tasks) {
  const messages = [{ role: 'system', content: task.system }];
  for (let index = 0; index < 18; index += 1) {
    messages.push({
      role: 'assistant',
      content: `Historical analysis ${index}: routine background notes that are no longer decision-relevant. `.repeat(3),
    });
    messages.push({
      role: 'user',
      content: `Historical request ${index}: investigate an obsolete option and retain no final decision. `.repeat(3),
    });
  }
  messages.push({ role: 'user', content: task.current });
  for (const method of ['none', 'pruner_v1']) {
    cases.push({
      json: {
        task_id: task.id,
        method,
        session_id: `n8n:${task.id}:${method}`,
        task_state: task.taskState,
        messages,
      },
    });
  }
}
return cases;

const envelope = $json;
let response = envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;

// n8n 2.6.x 的 CLI 执行器可能把 HTTP 响应暴露为 IncomingMessage，
// 此时响应 JSON 仍然完整保存在 _readableState.buffer 中。
if (!Array.isArray(response.messages)) {
  const chunks = envelope?._readableState?.buffer;
  if (Array.isArray(chunks)) {
    const bytes = [];
    for (const chunk of chunks) {
      const data = Array.isArray(chunk?.data) ? chunk.data : (Array.isArray(chunk) ? chunk : []);
      bytes.push(...data);
    }
    if (bytes.length > 0) {
      const decoded = typeof Buffer !== 'undefined'
        ? Buffer.from(bytes).toString('utf8')
        : String.fromCharCode(...bytes);
      response = JSON.parse(decoded);
    }
  }
}

const source = $('Build A/B Cases').item.json;
const taskId = String(source.task_id || '');
const method = String(source.method || '');
const required = {
  incident: ['Aurora-17', 'INC-2048', 'ROLLBACK'],
  release: ['Atlas-5', 'BLOCKED', 'security gate'],
  migration: ['Northstar', 'eu-central', '02:00 UTC'],
};
const rendered = JSON.stringify(response.messages || []);
const terms = required[taskId] || [];
const missing = terms.filter((term) => !rendered.includes(term));
const metrics = response.metrics || {};
const rawError = response.error || envelope.error;
const transportError = rawError ? String(rawError.message || rawError) : '';
return {
  json: {
    task_id: taskId,
    method,
    session_id: response.session_id || source.session_id,
    success: !transportError && missing.length === 0,
    missing_terms: missing,
    transport_error: transportError,
    full_context_tokens: Number(metrics.last_full_context_tokens || 0),
    served_context_tokens: Number(metrics.last_served_context_tokens || 0),
    gross_input_savings_rate: Number(metrics.gross_input_savings_rate || 0),
    model_input_budget_violation_count: Number(metrics.model_input_budget_violation_count || 0),
    before_model_calls: Number(metrics.before_model_calls || 0),
  },
};
